-- Owning-role privileges follow INHERIT; the ability to SET ROLE is separate.
CREATE ROLE owner_group;
CREATE ROLE set_only;
CREATE ROLE inherited_owner;
GRANT owner_group TO set_only WITH INHERIT FALSE, SET TRUE;
GRANT owner_group TO inherited_owner WITH INHERIT TRUE, SET FALSE;
GRANT CREATE ON SCHEMA public TO owner_group;
SET ROLE owner_group;
CREATE TABLE group_table(id integer);
CREATE FUNCTION group_function() RETURNS integer LANGUAGE sql AS 'SELECT 1';
CREATE TYPE group_choice AS ENUM('a');
RESET ROLE;
SET SESSION AUTHORIZATION set_only;
ALTER TABLE group_table OWNER TO owner_group;
ALTER TABLE group_table ADD COLUMN denied integer;
ALTER FUNCTION group_function() STABLE;
ALTER TYPE group_choice ADD VALUE 'denied';
RESET SESSION AUTHORIZATION;
SET SESSION AUTHORIZATION inherited_owner;
ALTER TABLE group_table ADD COLUMN allowed integer;
ALTER FUNCTION group_function() STABLE;
ALTER TYPE group_choice ADD VALUE 'allowed';
SET ROLE owner_group;
RESET SESSION AUTHORIZATION;
DROP TABLE group_table;
DROP FUNCTION group_function();
DROP TYPE group_choice;
DROP OWNED BY owner_group;
DROP ROLE set_only;
DROP ROLE inherited_owner;
DROP ROLE owner_group;
